        inputs: toast
        outputs: text: string, show: signal
        functionScript:
          | const t = Inputs.toast;
          | if (!t || !t.text) return;
          | Outputs.text = t.text;
          | Outputs.show();
    to_on: Switch "Toast showing"
    to_timer: Timer "2.6 seconds" {duration: 2600}
  wires (from.port -> to.port):
    to_sub.value -> to_fn.in-toast
    to_fn.out-text -> to_text.text
    to_fn.out-show -> to_on.on
    to_fn.out-show -> to_timer.restart
    to_timer.timerFinished -> to_on.off
